'use strict';
// One-shot independent review of the material actually generated by Gemini.
// No local API keys, no Supabase writes, no retry loops.
const fs=require('node:fs'),url='https://heva-online.vercel.app/api/review';
const output={fecha:new Date().toISOString(),prueba:'HEVA Review independiente de guía real Gemini',estado:'sin_ejecutar'};
const save=()=>{fs.mkdirSync('qa-review',{recursive:true});fs.writeFileSync('qa-review/resultado.json',JSON.stringify(output,null,2));};
(async()=>{
 try{
  const material=JSON.parse(fs.readFileSync('qa-source/material-recibido.json','utf8'));
  output.material={titulo:material.titulo,tipoMaterial:material.tipoMaterial,versionPedagogica:material.versionPedagogica,autor:material.autoriaIA?.proveedor};
  if(material.versionPedagogica!==3||material.autoriaIA?.proveedor!=='gemini')throw Error('El artefacto previo no es la guía esperada.');
  const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({accion:'revisar',material}),signal:AbortSignal.timeout(59000)});
  const body=await response.json().catch(()=>null);
  output.http=response.status;output.exito=body?.exito===true;
  output.etapa=body?.etapa||null;output.codigo=body?.codigo||null;
  output.error=String(body?.error||body?.detalle||'').slice(0,600);
  const r=body?.revision;
  output.informe=r?{
   proveedor:r.proveedor,modelo:r.modelo,estado:r.estado,integridadInforme:r.integridadInforme,
   criterios:r.criterios?.map(c=>({id:c.id,estado:c.estado,fundamento:String(c.fundamento||'').slice(0,300)})),
   hallazgos:r.hallazgos?.length||0,
   incidenciasDocumentales:r.incidenciasDocumentales?.length||0,
   contrastesDocumentales:r.contrastesDocumentales?.length||0,
   alcance:r.alcance||null
  }:null;
  if(r)fs.writeFileSync('qa-review/revision-real.json',JSON.stringify(r,null,2));
  save();console.log('REVISION_REAL '+JSON.stringify(output).slice(0,5200));
  output.estado=output.exito?'revisor_independiente_confirmado':'revision_fallida_o_bloqueada';
  save();if(!output.exito)process.exitCode=2;
 }catch(e){output.estado='error_de_transporte';output.error=String(e.message||e).slice(0,300);console.log('REVISION_ERROR '+output.error);save();process.exitCode=2;}
})();
